import time


class RetryError(Exception):
    pass


def retry(fn, attempts=3, base_delay=0.1, sleep=time.sleep, retry_on=(Exception,)):
    """Call fn() up to `attempts` times with exponential backoff (base, 2*base, 4*base...)."""
    last = None
    for attempt in range(1, attempts):
        try:
            return fn()
        except retry_on as exc:
            last = exc
            sleep(base_delay * 2 ** attempt)
    raise RetryError(f"gave up after {attempts} attempts") from last

