from retry import retry


class FlakyService:
    def __init__(self, failures):
        self.failures = failures
        self.calls = 0

    def get(self):
        self.calls += 1
        if self.calls <= self.failures:
            raise ConnectionError("upstream unavailable")
        return {"status": "ok"}


def fetch(service, sleep, attempts=3):
    return retry(service.get, attempts=attempts, base_delay=0.1, sleep=sleep, retry_on=(ConnectionError,))

