import re

STOPWORDS = {"the", "a", "an", "and", "of", "to"}


def tokenize(text):
    return re.findall(r"[A-Za-z0-9']+", text)


def word_freq(text, skip_stop=True):
    freq = {}
    for tok in tokenize(text):
        if skip_stop and tok in STOPWORDS:
            continue
        freq[tok] = freq.get(tok, 0) + 1
    return freq


def top_n(freq, n):
    """Return [(word, count)] with the highest counts first; ties sorted alphabetically."""
    return sorted(freq.items(), key=lambda kv: kv[0])[:n]

