ROLES = {
    "viewer": {"doc:read"},
    "editor": {"doc:write"},
    "admin": {"*"},
}
INHERITS = {
    "editor": ["viewer"],
    "admin": ["editor"],
}


def role_permissions(role):
    perms = set(ROLES.get(role, ()))
    for parent in INHERITS.get(role, []):
        perms |= role_permissions(parent)
    return perms


def effective_permissions(user):
    perms = set()
    for role in user.get("roles", []):
        perms |= role_permissions(role)
    perms |= set(user.get("grants", []))
    return perms


def can(user, action):
    if action in user.get("denies", ()):
        return False
    perms = effective_permissions(user)
    if "*" in perms or action in perms:
        return True
    resource = action.split(":")[0]
    return resource + ":*" in perms

