class OutOfStock(Exception):
    pass


class Inventory:
    def __init__(self, stock):
        self.stock = dict(stock)
        self.reserved = {}
        self._orders = {}

    def available(self, sku):
        return self.stock.get(sku, 0) - self.reserved.get(sku, 0)

    def reserve(self, order_id, lines):
        """Reserve every line or none. lines: {sku: qty}."""
        if order_id in self._orders:
            raise ValueError(f"order {order_id} already reserved")
        for sku, qty in lines.items():
            if self.available(sku) < qty:
                raise OutOfStock(sku)
            self.reserved[sku] = self.reserved.get(sku, 0) + qty
        self._orders[order_id] = lines

    def release(self, order_id):
        lines = self._orders.pop(order_id)
        for sku, qty in lines.items():
            self.reserved[sku] -= qty

    def commit(self, order_id):
        lines = self._orders.pop(order_id)
        for sku, qty in lines.items():
            self.reserved[sku] -= qty
            self.stock[sku] -= qty

