class DedupePipeline:
    """Drops events already seen in the last `ttl` seconds (inclusive)."""

    def __init__(self, ttl=60):
        self.ttl = ttl
        self.seen = {}
        self.dropped = 0

    def _expire(self, now):
        for key, first_seen in self.seen.items():
            if now - first_seen >= self.ttl:
                del self.seen[key]

    def accept(self, event, now):
        self._expire(now)
        key = event["id"]
        if key in self.seen:
            self.dropped += 1
            return False
        self.seen[key] = now
        return True

    def accept_all(self, events, now):
        return [e for e in events if self.accept(e, now)]

