            if now - first_seen > self.ttl:
                del self.seen[key]

    def accept(self, event, now):
        self._expire(now)
        key = (event["source"], event["id"])
        if key in self.seen:
            self.dropped += 1
            return False
        self.seen[key] = now
        return True

    def accept_all(self, events, now):
        return [e for e in events if self.accept(e, now)]

