import heapq
import itertools


class Scheduler:
    """Higher priority number runs first; ties run in insertion order; jobs run only once due."""

    def __init__(self):
        self._heap = []
        self._counter = itertools.count()

    def add(self, name, priority, run_at=0):
        heapq.heappush(self._heap, (-priority, next(self._counter), name, run_at))

    def pop_ready(self, now):
        """Return the name of the best job whose run_at <= now, or None."""
        skipped = []
        result = None
        while self._heap:
            item = heapq.heappop(self._heap)
            if item[3] <= now:
                result = item[2]
                break
            skipped.append(item)
        for item in skipped:
            heapq.heappush(self._heap, item)
        return result

    def __len__(self):
        return len(self._heap)

