            raise ValueError(f"{account} already exists")
        self.balances[account] = balance

    def transfer(self, src, dst, amount, fee_bps=0):
        """Move `amount` from src to dst; the sender also pays a fee, rounded half-up to the cent."""
        if amount <= 0:
            raise ValueError("amount must be positive")
        for account in (src, dst):
            if account not in self.balances:
                raise KeyError(account)
        fee = (amount * fee_bps + 5000) // 10000
        if self.balances[src] < amount + fee:
            raise InsufficientFunds(src)
        self.balances[src] -= amount + fee
        self.balances[dst] += amount
        self.fees += fee
        self.history.append((src, dst, amount, fee))

    def total(self):
        """Money in the system; must never change by transferring."""
        return sum(self.balances.values()) + self.fees

