import base64
import hashlib
import hmac
import json
import time


class InvalidToken(Exception):
    pass


class TokenExpired(InvalidToken):
    pass


def b64url_encode(raw):
    return base64.urlsafe_b64encode(raw).rstrip(b"=").decode()


def b64url_decode(text):
    return base64.urlsafe_b64decode(text)


def _mac(payload, secret):
    return b64url_encode(hmac.new(secret.encode(), payload.encode(), hashlib.sha256).digest())


def sign(claims, secret, now=None, ttl=3600):
    now = int(time.time()) if now is None else now
    body = dict(claims, iat=now, exp=now + ttl)
    payload = b64url_encode(json.dumps(body, separators=(",", ":"), sort_keys=True).encode())
    return payload + "." + _mac(payload, secret)


def verify(token, secret, now=None, leeway=0):
    """A token is valid while now < exp (+ leeway seconds of tolerated clock skew)."""
    now = int(time.time()) if now is None else now
    try:
        payload, sig = token.split(".")
    except ValueError:
        raise InvalidToken("malformed token")
    if not hmac.compare_digest(sig, _mac(payload, secret)):
        raise InvalidToken("bad signature")
    claims = json.loads(b64url_decode(payload))
    if now > claims["exp"] - leeway:
        raise TokenExpired("token expired")
    return claims

