    def __init__(self, repo):
        self.repo = repo
        self._items = {}
        self._lists = {}

    def get(self, pid):
        if pid not in self._items:
            self._items[pid] = self.repo.fetch(pid)
        return dict(self._items[pid])

    def by_category(self, category):
        if category not in self._lists:
            self._lists[category] = self.repo.query_category(category)
        return [dict(r) for r in self._lists[category]]

    def update(self, pid, **fields):
        old = self.get(pid)
        self.repo.save(pid, fields)
        self._items.pop(pid, None)
        self._lists.pop(old["category"], None)
        self._lists.pop(fields.get("category", old["category"]), None)

