    """Builds one check per field from a rules dict and runs them in rule order."""

    def __init__(self, rules):
        self.checks = []
        for field, spec in rules.items():
            self.checks.append(lambda rec: _check(rec, field, spec))

    def validate(self, rec):
        errors = []
        for check in self.checks:
            message = check(rec)
            if message:
                errors.append(message)
        return errors


def _check(rec, field, spec):
    value = rec.get(field)
    if not value:
        return f"{field} is required" if spec.get("required") else None
    if "max_len" in spec and len(value) > spec["max_len"]:
        return f"{field} must be at most {spec['max_len']} characters"
    if "min" in spec and value < spec["min"]:
        return f"{field} must be >= {spec['min']}"
    return None

