        if sku not in self.catalog:
            raise KeyError(sku)
        self.catalog[sku] = cents

    def price(self, name, region="us"):
        base = self._base(name, set())
        return base + base * self.tax_pct[region] // 100

    def _base(self, name, path):
        if name in path:
            raise CycleError(name)
        if name in self._memo:
            return self._memo[name]
        if name in self.catalog:
            return self.catalog[name]
        if name not in self.bundles:
            raise KeyError(name)
        path.add(name)
        spec = self.bundles[name]
        total = sum(self._base(child, path) * qty for child, qty in spec["items"].items())
        total -= total * spec["discount_pct"] // 100
        self._memo[name] = total
        return total

